//! Verification fixtures: throwaway keys, generated once with the OpenSSL
//! command line. Nothing here is secret; the keys were never used elsewhere.
//!
//! Each signature is over the digest of `MESSAGE` with the hash at the same
//! index of `HashAlgorithm::ALL` (SHA-256, SHA-384, SHA-512). Certificates
//! come from `openssl req -x509 -newkey ... -days 36500`; signatures from
//! `openssl pkeyutl -sign -in <digest>` (with `-pkeyopt rsa_padding_mode:pss`,
//! `rsa_pss_saltlen:<digest length>` and `rsa_mgf1_md:<hash>` for PSS).

pub(super) const MESSAGE: &[u8] = b"probe-core verify fixture";

